// One item per post: the endpoint that lists its comments, and the post's ID or link.
return [
  { json: { endpoint: 'douyin.videos.comments.list', params: { id: 'REPLACE_WITH_VIDEO_ID' } } },
  { json: { endpoint: 'wechat_mp.articles.comments.list', params: { url: 'https://mp.weixin.qq.com/s/REPLACE_ME' } } },
];

// Keywords in any language; matching ignores case.
const keywords = ['broken', 'scam', 'fake', 'too expensive'];
// Keep only items not seen in earlier runs. Static data persists only when the
// workflow is active (production runs), not in manual test runs.
const seen = $getWorkflowStaticData('global');
seen.ids = seen.ids || [];
const known = new Set(seen.ids);
const fresh = $input.all().filter((item) => item.json.id && !known.has(item.json.id));
seen.ids = [...seen.ids, ...fresh.map((item) => item.json.id)].slice(-2000);
return fresh
  .filter((item) => keywords.some((k) => (item.json.text || '').toLowerCase().includes(k.toLowerCase())))
  .map((item) => {
    const c = item.json;
    const who = (c.author && (c.author.name || c.author.username)) || 'Someone';
    return { json: { text: `Comment alert: ${who}: ${(c.text || '').slice(0, 300)}` } };
  });
